   946      return true;
   947    }
   948    *state = copy;
   949
   950    if (ParseOneCharToken(state, 'D') && ParseCharClass(state, "tT") &&
   951        ParseExpression(state) && ParseOneCharToken(state, 'E')) {
   952      return true;
   953    }
   954    *state = copy;
   955
   956    if (ParseOneCharToken(state, 'U') && ParseSourceName(state) &&
   957        ParseType(state)) {
   958      return true;
   959    }
